    summary = { "Night elves protect Ashenvale by living carefully and replanting.", { "Night elves build big fires every night.", "Travelers often get lost in Ashenvale.", "Sentinels cut down trees for the city." } } },
  { lv = 1, text = "Thrall, the young Warchief, led the orcs across the sea to Kalimdor. They were tired of war and needed a home of their own. In a dry red land they named Durotar, after Thrall's father, they built the city of Orgrimmar with their own hands.",
    infer = { "Why did the orcs probably name the land after Thrall's father?", "to honor his memory", { "because he built the city", "because he still led the orcs", "because the land was red" } },
    purpose = { "to explain how the orcs found and built a new home", { "to persuade orcs to go back to war", "to describe the weather in Kalimdor", "to teach readers how to sail" } },
    summary = { "Thrall led the orcs to Kalimdor, where they built a new home.", { "The orcs sailed away to start a war.", "Thrall's father built Orgrimmar alone.", "Durotar is a green and rainy land." } } },
  { lv = 1, text = "Deep under the snowy peaks, the dwarves of Ironforge keep a great forge burning day and night. Its fires have not gone out in hundreds of years. Every dwarf child learns that the forge is the heart of the city, and many dream of one day hammering at its anvils.",
    infer = { "What can you infer about the great forge?", "It is very important to the dwarves.", { "It was built last year.", "Dwarves are scared of it.", "It is used only for cooking." } },
    purpose = { "to describe the forge and why dwarves value it", { "to warn readers about the danger of fire", "to persuade readers to become blacksmiths", "to tell a scary story" } },
    summary = { "Ironforge's ancient forge is the proud heart of dwarven life.", { "Dwarf children are not allowed near fire.", "The great forge went out last year.", "Ironforge is built on a sunny beach." } } },
  { lv = 1, text = "Murlocs live along the coasts of Azeroth. They build huts from reeds and shells and talk in gurgling sounds. Many travelers think murlocs are only pests, but scholars who study them have found that murloc villages share food and care for their young together.",
    infer = { "What does the passage suggest about murlocs?", "They are more caring than many travelers think.", { "They live in the desert.", "They do not have villages.", "They never share food." } },
    purpose = { "to give a fuller picture of how murlocs live", { "to warn travelers to avoid the coast", "to tell a joke about murlocs", "to explain how to catch fish" } },
    summary = { "Murlocs, often seen as pests, actually live in caring villages.", { "Murlocs build huts from stone and iron.", "Scholars agree murlocs are only pests.", "Murlocs live alone in deep caves." } } },
  { lv = 2, text = "Gadgetzan sits in the middle of the Tanaris desert. Its goblin rulers made one firm rule: no fighting inside the town. Heroes of every race trade, rest and swap stories there, watched by tough bruisers who throw out anyone who starts a brawl. Water is so precious that even the water tower is guarded.",
    infer = { "Why might heroes of every race like visiting Gadgetzan?", "It is a safe place to trade and rest.", { "The town gives away free water.", "The desert there is cool and rainy.", "They are allowed to fight there." } },
    purpose = { "to inform readers about Gadgetzan and its rules", { "to convince readers to live in the desert", "to tell the story of one famous brawl", "to explain how to build a water tower" } },
    summary = { "Gadgetzan is a guarded desert town where all races trade in peace.", { "Gadgetzan is a town where fighting is allowed.", "The goblins of Gadgetzan have plenty of water.", "Tanaris is a forest full of rivers." } } },
  { lv = 2, text = "The Forsaken were once people of Lordaeron, but a terrible plague turned them into undead servants. When they broke free, they chose their own path. Many outsiders fear them, yet the Forsaken insist they are still people who can think and choose for themselves.",
    infer = { "What do the Forsaken most want others to understand?", "They can still make their own choices.", { "They want to be feared.", "They do not care what others think.", "They want to return to the plague." } },
    purpose = { "to explain who the Forsaken are and how they see themselves", { "to make readers laugh", "to persuade readers to fear the Forsaken", "to give directions to Lordaeron" } },
    summary = { "Once cursed, the Forsaken broke free and now choose their own path.", { "The Forsaken are humans who live in Stormwind.", "The plague made the Forsaken into heroes.", "The Forsaken never broke free." } } },
  { lv = 2, text = "Gnomes once lived in the bright city of Gnomeregan, full of whirring machines. When it was overrun by troggs and filled with poisonous fumes, the gnomes fled to Ironforge. Instead of giving up, they kept inventing, and they still plan to take their home back.",
    infer = { "What does the passage suggest about gnomes?", "They are hopeful and do not give up easily.", { "They dislike machines.", "They have forgotten Gnomeregan.", "They want to stay in Ironforge forever." } },
    purpose = { "to tell how the gnomes lost their city but kept their hope", { "to explain how to build a machine", "to persuade readers to fight troggs", "to describe a fun day in Gnomeregan" } },
    summary = { "After losing Gnomeregan, the gnomes stayed hopeful and kept inventing.", { "Gnomes built Ironforge after losing a war.", "Troggs and gnomes now share Gnomeregan.", "Gnomes stopped inventing after they fled." } } },
  { lv = 2, text = "Before maps were common, tauren hunters marked trails by stacking stones into small towers called cairns. A traveler who found a cairn knew that water or shelter was near. Today, many tauren still add a stone to a cairn when they pass, to thank those who walked the path before them.",
    infer = { "Why do tauren still add stones to cairns today?", "to show respect for travelers of the past", { "to make the trail harder to walk", "because maps are not allowed", "to mark where treasure is buried" } },
    purpose = { "to explain a tauren tradition and its meaning", { "to persuade readers to build towers", "to describe a scary journey", "to teach readers how to draw maps" } },
    summary = { "Tauren cairns once marked trails and are now a way to give thanks.", { "Tauren hunters never used trails.", "Cairns are towers built to keep travelers out.", "Tauren use maps instead of cairns today." } } },
  { lv = 3, text = "Storytellers across Azeroth still tell the tale of Mount Hyjal. When demons of the Burning Legion tried to destroy the World Tree, orcs, humans and night elves, who had been enemies, fought side by side. Some storytellers end the tale with a question: if old enemies stood together once, why not again?",
    infer = { "What does the storytellers' question suggest?", "Former enemies might work together again.", { "The demons won the battle.", "The World Tree was not important.", "Storytellers want a new war to start." } },
    purpose = { "to remind readers that enemies once united for a greater cause", { "to describe the shape of the World Tree", "to convince readers that demons are friendly", "to list every hero in the battle" } },
    summary = { "At Mount Hyjal, old enemies united to save the World Tree.", { "The Burning Legion planted the World Tree.", "Orcs and humans fought each other at Hyjal.", "Night elves defended Hyjal all alone." } } },
  { lv = 3, text = "Supporters of the Steamwheedle Cartel say its neutral towns keep trade alive between Horde and Alliance. Critics reply that the goblins stay neutral only because it makes them rich. Both sides agree on one thing: without places like Booty Bay and Gadgetzan, many travelers would have nowhere safe to rest.",
    infer = { "What can you infer about the goblins' neutrality?", "It helps both travelers and the goblins' business.", { "It makes travelers less safe.", "It means goblins never trade.", "It was ordered by one faction." } },
    purpose = { "to present different views about the Cartel's neutrality", { "to tell a funny goblin joke", "to persuade readers that goblins are greedy", "to share a recipe from Booty Bay" } },
    summary = { "People disagree on why the Cartel is neutral, but its towns help travelers.", { "Everyone agrees the goblins are greedy.", "Booty Bay and Gadgetzan belong to one faction.", "The Cartel has closed all of its towns." } } },
  { lv = 3, text = "Jaina Proudmoore founded Theramore, a port on the coast of Kalimdor not far from the orcs' new home. She was a leader of the Alliance and Thrall led the Horde, yet the two often met to keep the peace. They knew one spark of anger could start another war, so they solved problems by talking.",
    infer = { "What does the passage suggest about Jaina and Thrall?", "They trusted each other enough to talk through problems.", { "They wanted to start a war.", "They never met each other.", "They lived in the same city." } },
    purpose = { "to show how two leaders worked to keep the peace", { "to describe the weather in Kalimdor", "to persuade readers to join one faction", "to tell a scary story about Theramore" } },
    summary = { "Jaina and Thrall led rival sides but worked together for peace.", { "Jaina and Thrall fought many battles.", "Theramore was the capital of the Horde.", "Thrall built Theramore for Jaina." } } },
  { lv = 3, text = "When the Scourge spread across the north, the Argent Dawn formed to fight it. Its members came from many races and from both factions. They agreed to set aside old quarrels, because the danger to everyone was greater than any argument between them.",
    infer = { "Why did members from both factions join the Argent Dawn?", "They faced a danger that threatened everyone.", { "They were paid by the Scourge.", "They had nothing else to do.", "They wanted to fight each other." } },
    purpose = { "to explain why the Argent Dawn brought rivals together", { "to describe the weather in the north", "to persuade readers to join the Scourge", "to tell a bedtime story" } },
    summary = { "The Argent Dawn united many races against the Scourge.", { "The Argent Dawn helped the Scourge spread.", "Only humans joined the Argent Dawn.", "The Argent Dawn started new quarrels." } } },
}

