-- Grammar and sentence correction: one correct sentence, three with errors.
D.GRAMMAR = {
  { lv = 1, a = "The orcs were ready for the journey.", d = { "The orcs was ready for the journey.", "The orcs is ready for the journey.", "The orcs be ready for the journey." }, why = "Use 'were' with a plural subject like 'orcs'." },
  { lv = 1, a = "Thrall and Jaina met to talk about peace.", d = { "Thrall and Jaina meets to talk about peace.", "Thrall and Jaina meeting to talk about peace.", "Thrall and Jaina has met to talks about peace." }, why = "Two people take a plural verb, and 'met' is the past tense of 'meet'." },
  { lv = 1, a = "The dwarves carried their axes up the hill.", d = { "The dwarves carried there axes up the hill.", "The dwarves carried they're axes up the hill.", "The dwarves carryed their axes up the hill." }, why = "'Their' shows belonging, and 'carry' becomes 'carried'." },
  { lv = 1, a = "It's going to rain in Elwynn Forest today.", d = { "Its going to rain in Elwynn Forest today.", "Its' going to rain in Elwynn Forest today.", "It going to rain in Elwynn Forest today." }, why = "'It's' is short for 'it is'." },
  { lv = 1, a = "There are three wolves near the camp.", d = { "There is three wolves near the camp.", "Their are three wolves near the camp.", "They're are three wolves near the camp." }, why = "Use 'there are' for more than one, and 'there' for a place." },
  { lv = 1, a = "We have seen many gryphons today.", d = { "We have saw many gryphons today.", "We has seen many gryphons today.", "We seen many gryphons today." }, why = "Use 'have seen', not 'have saw' or 'seen' alone." },
  { lv = 1, a = "The kodo ran faster than the zhevra.", d = { "The kodo ran more faster than the zhevra.", "The kodo ran fastest than the zhevra.", "The kodo runned faster than the zhevra." }, why = "'Faster' already means 'more fast', and the past of 'run' is 'ran'." },
  { lv = 2, a = "Each of the gnomes has a toolbox.", d = { "Each of the gnomes have a toolbox.", "Each of the gnomes are having a toolbox.", "Each of the gnome have a toolboxes." }, why = "'Each' is singular, so it takes 'has'." },
  { lv = 2, a = "She and I explored the caverns.", d = { "Her and me explored the caverns.", "Me and her explored the caverns.", "She and me explored the caverns." }, why = "Use the subject pronouns 'she' and 'I' before the verb." },
  { lv = 2, a = "I should have brought more water.", d = { "I should of brought more water.", "I should have bring more water.", "I should have brung more water." }, why = "Say 'should have', and the past of 'bring' is 'brought'." },
  { lv = 2, a = "The paladin gave the shield to Mara and me.", d = { "The paladin gave the shield to Mara and I.", "The paladin gave the shield to I and Mara.", "The paladin give the shield to Mara and me." }, why = "After 'to', use 'me' (try the sentence without 'Mara')." },
  { lv = 2, a = "Whose map is this?", d = { "Who's map is this?", "Whos map is this?", "Whose' map is this?" }, why = "'Whose' asks who owns something; 'who's' means 'who is'." },
  { lv = 2, a = "Who's ready to fly to Ratchet?", d = { "Whose ready to fly to Ratchet?", "Whos ready to fly to Ratchet?", "Who ready to fly to Ratchet?" }, why = "'Who's' is short for 'who is'." },
  { lv = 2, a = "Everyone in the inn was laughing.", d = { "Everyone in the inn were laughing.", "Everyone in the inn are laughing.", "Everyone in the inn laughing." }, why = "'Everyone' is singular, so it takes 'was'." },
  { lv = 3, a = "The goblin, who loved gold, opened a bank.", d = { "The goblin who loved gold, opened a bank.", "The goblin, who loved gold opened a bank.", "The goblin who, loved gold, opened a bank." }, why = "Extra information gets a comma on both sides." },
  { lv = 3, a = "Neither the troll nor the orc was late.", d = { "Neither the troll nor the orc were late.", "Neither the troll or the orc was late.", "Neither the troll nor the orc are late." }, why = "'Neither ... nor' with single nouns takes 'was'." },
  { lv = 3, a = "The night elves' forest is very old.", d = { "The night elfs' forest is very old.", "The night elve's forest is very old.", "The night elves forest's is very old." }, why = "The plural is 'elves', so the plural possessive is 'elves''." },
  { lv = 3, a = "The mage quickly cast a spell.", d = { "The mage quick cast a spell.", "The mage quickly casted a spell.", "The mage quicker cast a spell." }, why = "Use the adverb 'quickly'; the past of 'cast' is 'cast'." },
  { lv = 3, a = "After the storm, the sailors fixed the sails.", d = { "After the storm the sailors, fixed the sails.", "After, the storm the sailors fixed the sails.", "After the storm, the sailors fixes the sails." }, why = "Put the comma after the opening phrase 'After the storm'." },
  { lv = 3, a = "The tauren lifted the heavy log by himself.", d = { "The tauren lifted the heavy log by hisself.", "The tauren lifted the heavy log by itselves.", "The tauren lifted the heavy log by theirselves." }, why = "The correct word is 'himself'." },
}

